macro_rules! deps {
    () => {
        WfCheckingCtxt!();
    };
}

macro_rules! check_where_clauses {
    () => {
        deps!();
        # [doc = " Checks where-clauses and inline bounds that are declared on `def_id`."] # [instrument (level = "debug" , skip (wfcx))] pub (super) fn check_where_clauses < 'tcx > (wfcx : & WfCheckingCtxt < '_ , 'tcx > , def_id : LocalDefId) { let infcx = wfcx . infcx ; let tcx = wfcx . tcx () ; let predicates = tcx . predicates_of (def_id . to_def_id ()) ; let generics = tcx . generics_of (def_id) ; for param in & generics . own_params { if let Some (default) = param . default_value (tcx) . map (ty :: EarlyBinder :: instantiate_identity) { if ! default . has_param () { wfcx . register_wf_obligation (tcx . def_span (param . def_id) , matches ! (param . kind , GenericParamDefKind :: Type { .. }) . then (| | WellFormedLoc :: Ty (param . def_id . expect_local ())) , default . as_term () . unwrap () ,) ; } else { let GenericArgKind :: Const (ct) = default . kind () else { continue ; } ; let ct_ty = match ct . kind () { ty :: ConstKind :: Infer (_) | ty :: ConstKind :: Placeholder (_) | ty :: ConstKind :: Bound (_ , _) => unreachable ! () , ty :: ConstKind :: Error (_) | ty :: ConstKind :: Expr (_) => continue , ty :: ConstKind :: Value (cv) => cv . ty , ty :: ConstKind :: Unevaluated (uv) => { infcx . tcx . type_of (uv . def) . instantiate (infcx . tcx , uv . args) } ty :: ConstKind :: Param (param_ct) => { param_ct . find_const_ty_from_env (wfcx . param_env) } } ; let param_ty = tcx . type_of (param . def_id) . instantiate_identity () ; if ! ct_ty . has_param () && ! param_ty . has_param () { let cause = traits :: ObligationCause :: new (tcx . def_span (param . def_id) , wfcx . body_def_id , ObligationCauseCode :: WellFormed (None) ,) ; wfcx . register_obligation (Obligation :: new (tcx , cause , wfcx . param_env , ty :: ClauseKind :: ConstArgHasType (ct , param_ty) ,)) ; } } } } let args = GenericArgs :: for_item (tcx , def_id . to_def_id () , | param , _ | { if param . index >= generics . parent_count as u32 && let Some (default) = param . default_value (tcx) . map (ty :: EarlyBinder :: instantiate_identity) && ! default . has_param () { return default ; } tcx . mk_param_from_def (param) }) ; let default_obligations = predicates . predicates . iter () . flat_map (| & (pred , sp) | { # [derive (Default)] struct CountParams { params : FxHashSet < u32 > , } impl < 'tcx > ty :: TypeVisitor < TyCtxt < 'tcx > > for CountParams { type Result = ControlFlow < () > ; fn visit_ty (& mut self , t : Ty < 'tcx >) -> Self :: Result { if let ty :: Param (param) = t . kind () { self . params . insert (param . index) ; } t . super_visit_with (self) } fn visit_region (& mut self , _ : ty :: Region < 'tcx >) -> Self :: Result { ControlFlow :: Break (()) } fn visit_const (& mut self , c : ty :: Const < 'tcx >) -> Self :: Result { if let ty :: ConstKind :: Param (param) = c . kind () { self . params . insert (param . index) ; } c . super_visit_with (self) } } let mut param_count = CountParams :: default () ; let has_region = pred . visit_with (& mut param_count) . is_break () ; let instantiated_pred = ty :: EarlyBinder :: bind (pred) . instantiate (tcx , args) ; if instantiated_pred . has_non_region_param () || param_count . params . len () > 1 || has_region { None } else if predicates . predicates . iter () . any (| & (p , _) | p == instantiated_pred) { None } else { Some ((instantiated_pred , sp)) } }) . map (| (pred , sp) | { let pred = wfcx . normalize (sp , None , pred) ; let cause = traits :: ObligationCause :: new (sp , wfcx . body_def_id , ObligationCauseCode :: WhereClause (def_id . to_def_id () , sp) ,) ; Obligation :: new (tcx , cause , wfcx . param_env , pred) }) ; let predicates = predicates . instantiate_identity (tcx) ; assert_eq ! (predicates . predicates . len () , predicates . spans . len ()) ; let wf_obligations = predicates . into_iter () . flat_map (| (p , sp) | { let p = wfcx . normalize (sp , None , p) ; traits :: wf :: clause_obligations (infcx , wfcx . param_env , wfcx . body_def_id , p , sp) }) ; let obligations : Vec < _ > = wf_obligations . chain (default_obligations) . collect () ; wfcx . register_obligations (obligations) ; }
    };
}

check_where_clauses!();